internal sealed partial class SimRfqIntakeStore
{
    private string QuoteCopyRoot=>Path.Combine(Path.GetDirectoryName(dataPath)!,"quote-copies-v1");
    private static void QuoteRequire(bool value,string code,string message){if(!value)throw SimRfqIntakeProblem.Conflict(code,message);}
    private static void QuotePreparePermission(SimPersona persona)=>QuoteRequire(persona.IsActive&&persona.Can("rfq.quote.prepare"),"QUOTE_COPY_DENIED","Customer quote preparation is not assigned to this profile.");
    private static string QuoteGuid(string value){QuoteRequire(Guid.TryParseExact(value,"D",out _),"QUOTE_COPY_ID","Choose a valid PDF copy reference.");return value;}
    private string QuoteDraftPath(string id,SimPersona p)=>Path.Combine(QuoteCopyRoot,"drafts",EstimateHash(p.Id),QuoteGuid(id));
    private string QuoteArchivePath(string id)=>Path.Combine(QuoteCopyRoot,"copies",QuoteGuid(id)+".json");
    private string QuoteBlob(string hash){QuoteRequire(hash.Length==64&&hash.All(c=>c is >= '0' and <= '9' or >= 'A' and <= 'F'),"QUOTE_COPY_HASH","Invalid PDF content identity.");return Path.Combine(QuoteCopyRoot,"pdf",hash+".pdf");}
    private static string QuoteText(string? value,int limit,string label){var text=value?.Trim()??"";QuoteRequire(text.Length<=limit&&!text.Contains('\0'),"QUOTE_COPY_VALUES",label+" is too long or invalid.");return text;}
    private static string QuoteFileName(SimQuoteCustomerProjection p,DateTimeOffset at)=>p.Lines[0].RfqId+(p.Lines.Length>1?"-selected-lines":"")+"-DRAFT-"+at.UtcDateTime.ToString("yyyyMMdd-HHmmss")+".pdf";
    private async Task<(SimQuoteSourceLine Source,SimQuotePinnedLine? Pinned,SimQuoteCustomerLine? Customer)> QuoteLine(SimRfqIntakeRecord record,SimRfqLanes lane)
    {
        QuoteRequire(record.LibraryRfq is not null,"QUOTE_COPY_SCOPE","Choose an approved Library-backed RFQ line.");
        var s=FinalReviewView(record,lane).Summary;var blockers=new List<string>();
        if(!s.TechnicalComplete||!s.TechnicalPackageAvailable)blockers.Add("Confirm this line's approved technical package.");
        if(record.DeLeonScope!="LABOR_ONLY"&&!s.MaterialsComplete)blockers.Add("Complete Materials for the current BOM and quantity.");
        if(record.DeLeonScope!="MATERIAL_ONLY"&&!s.LaborComplete)blockers.Add("Complete Labor for the current definition and quantity.");
        if(s.Quantity<=0||s.CombinedUnitPrice is null or <0||s.Total is null or <0||s.QuoteTotal is null or <0||s.NreLines.Any(c=>c.Amount is null or <0))blockers.Add("Complete valid pricing, NRE and requested quantity.");
        blockers.AddRange(RfqSectionHoldBlockers(lane));
        if(QuotationEditBlocker(record.IntakeId,lane.Commercial,(await ReadDatasetAsync()).Records) is {} committed)blockers.Add(committed);
        var flags=s.MaterialPartFlags??[];if(flags.Any(f=>f.Intent!="PROPOSED_PART"||string.IsNullOrWhiteSpace(f.QuotedPartNumber)))blockers.Add("Enter a concrete proposed P/N before preparing customer output; an unidentified alternate is not a quoted part.");
        var pairs=EstimatePairs(record,lane);var pair=pairs.SingleOrDefault(p=>p.Id==CurrentEstimateReview(record,lane,pairs));
        if(pair is null)blockers.Add("Complete the requested estimate sections before preparing output.");
        else _=await VerifyEstimatePair(record,lane,pair);
        var routes=await PartEstimateRoutes(record,lane);
        var differences=flags.Select(f=>new SimQuoteDisclosure(f.Find,f.ApprovedPartNumbers,f.QuotedPartNumber??"Not identified",routes.Any(r=>r.Index==f.Index&&r.Status=="Customer response required")?"Customer approval required before proceeding":"Part review pending - approval required before proceeding")).ToArray();
        var token=pair is null?null:EstimateHash(new{pair.Id,work=FinalSourceToken(record,lane),routes,differences});
        var a=record.Assemblies.Single();var source=new SimQuoteSourceLine(record.IntakeId,record.LibraryRfq!.LineNumber,a.AssemblyNumber,a.Revision,a.Quantity,record.DeLeonScope,pair?.Id,token,blockers.Count==0,blockers.ToArray(),pair?.MaterialsVersion,pair?.LaborVersion);
        if(blockers.Count>0)return(source,null,null);
        var charges=s.NreLines.Select(c=>new SimQuoteCharge(c.Label,c.Amount!.Value)).Concat((s.MaterialSupplemental?.Charges??[]).Where(c=>c.Treatment!="BLEND").Select(c=>new SimQuoteCharge(c.Description,c.SellAmount,c.Treatment))).ToArray();
        var line=new SimQuoteCustomerLine(record.IntakeId,a.AssemblyNumber,a.Revision,a.Quantity,s.Description,s.CombinedUnitPrice!.Value,s.Total!.Value,s.QuoteTotal!.Value,charges,s.MaterialLongestLeadDays is {} days?LeadDisplay(days):null,s.ManufacturingLead,differences,s.CustomerSuppliedItems??[]);
        return(source,new(pair!,token!),line);
    }
    internal async Task<SimQuoteSourceView> ReadQuoteSource(string id,SimPersona persona)
    {
        QuotePreparePermission(persona);await gate.WaitAsync();try{var anchor=await RequireRfqRecord(id);QuoteRequire(anchor.LibraryRfq is not null,"QUOTE_COPY_SCOPE","Choose an independent RFQ line.");var dataset=await ReadDatasetAsync();var parent=dataset.Records.Single(r=>r.IntakeId==anchor.LibraryRfq!.ParentIntakeId);var lanes=await ReadRfqLanes();var list=new List<SimQuoteSourceLine>();foreach(var a in parent.Assemblies.OrderBy(a=>a.LineNumber)){var lineId=SimAssemblyProjects.Label(parent.IntakeId,a);try{var record=await RequireRfqRecord(lineId);list.Add((await QuoteLine(record,lanes.GetValueOrDefault(lineId)??new(new(),new()))).Source);}catch(SimRfqIntakeProblem){list.Add(new(lineId,a.LineNumber,a.AssemblyNumber,a.Revision,a.Quantity,a.Scope??parent.DeLeonScope,null,null,false,["Awaiting approved package and completed estimates."],null,null));}}return new(1,parent.IntakeId,parent.Customer.CustomerName,list.ToArray(),Copies:await QuoteCopiesForParent(parent.IntakeId));}finally{gate.Release();}
    }
    private async Task<(SimQuoteCustomerProjection Projection,SimQuotePinnedLine[] Lines)> QuoteProjection(string id,SimQuoteDraftRequest request,SimPersona persona,DateTimeOffset at)
    {
        QuotePreparePermission(persona);_=QuoteGuid(request.RequestId);QuoteRequire(request.Lines is {Length:>0 and <=25}&&request.Lines.Select(l=>l.RfqId).Distinct().Count()==request.Lines.Length,"QUOTE_COPY_LINES","Select up to 25 distinct eligible RFQ lines.");
        var anchor=await RequireRfqRecord(id);QuoteRequire(anchor.LibraryRfq is not null,"QUOTE_COPY_SCOPE","Choose a Library RFQ line.");var lanes=await ReadRfqLanes();var pinned=new List<SimQuotePinnedLine>();var customers=new List<(int Number,SimQuoteCustomerLine Line)>();
        foreach(var selected in request.Lines){var record=await RequireRfqRecord(selected.RfqId);QuoteRequire(record.LibraryRfq?.ParentIntakeId==anchor.LibraryRfq!.ParentIntakeId&&record.Customer==anchor.Customer,"QUOTE_COPY_SCOPE","Select lines from this same customer request.");var line=await QuoteLine(record,lanes.GetValueOrDefault(record.IntakeId)??new(new(),new()));QuoteRequire(line.Source.Eligible,"QUOTE_COPY_INCOMPLETE",string.Join(" ",line.Source.Blockers));QuoteRequire(line.Source.EstimateId==selected.EstimateId&&line.Source.Token==selected.Token,"QUOTE_COPY_STALE","This line's estimate or part decisions changed. Refresh the selected lines and preview again.");pinned.Add(line.Pinned!);customers.Add((line.Source.LineNumber,line.Customer!));}
        await VerifyQuoteRevisionBases(pinned.ToArray(),request.RevisionOf);var ordered=customers.OrderBy(x=>x.Number).Select(x=>x.Line).ToArray();return(new(anchor.LibraryRfq!.ParentIntakeId,QuoteText(request.Reference,150,"Reference") is {Length:>0} reference?reference:null,at.UtcDateTime.ToString("MM/dd/yyyy"),anchor.Customer.CustomerName,"USD",ordered,ordered.Sum(l=>l.Total),QuoteText(request.QuotedDelivery,200,"Quoted delivery") is {Length:>0} delivery?delivery:null,QuoteText(request.Terms,4000,"Terms") is {Length:>0} terms?terms:null),pinned.ToArray());
    }
    private async Task VerifyQuoteLines(SimQuotePinnedLine[] lines)
    {
        var lanes=await ReadRfqLanes();foreach(var selected in lines){var record=await RequireRfqRecord(selected.Pair.RfqId);var current=await QuoteLine(record,lanes.GetValueOrDefault(record.IntakeId)??new(new(),new()));QuoteRequire(current.Source.Eligible&&current.Pinned?.Pair.Id==selected.Pair.Id&&current.Pinned.SourceToken==selected.SourceToken,"QUOTE_COPY_STALE","A selected estimate or part decision changed. Preview the current work again before saving a copy.");}
    }
    private static string DraftHash(SimQuoteDraftRecord record)=>EstimateHash(record with{ContentHash=""});
    private static string CopyHash(SimQuoteCopyRecord record)=>EstimateHash(record with{ContentHash=""});
    private async Task<SimQuoteDraftRecord> QuoteDraft(string id,SimPersona p)
    {
        var path=Path.Combine(QuoteDraftPath(id,p),"draft.json");QuoteRequire(File.Exists(path),"QUOTE_DRAFT_UNAVAILABLE","This prepared PDF is unavailable to this user.");var record=JsonSerializer.Deserialize<SimQuoteDraftRecord>(await File.ReadAllTextAsync(path),jsonOptions)!;QuoteRequire(record.Id==id&&record.OwnerId==p.Id&&record.ContentHash==DraftHash(record),"QUOTE_COPY_INTEGRITY","The prepared PDF record could not be verified.");return record;
    }
    private async Task<SimQuoteDraftView> DraftView(SimQuoteDraftRecord record,SimPersona p)
    {
        var directory=QuoteDraftPath(record.Id,p);var bytes=await File.ReadAllBytesAsync(Path.Combine(directory,"quotation.pdf"));QuoteRequire(PartHashBytes(bytes)==record.Sha256,"QUOTE_COPY_INTEGRITY","Prepared PDF integrity check failed.");var pages=JsonSerializer.Deserialize<string[]>(await File.ReadAllTextAsync(Path.Combine(directory,"pages.json")),jsonOptions)!;return new(1,record.Id,record.ContentHash,$"/api/sim/rfqs/{record.Lines[0].Pair.RfqId}/quote-copies/drafts/{record.Id}/pdf",QuoteFileName(record.Projection,record.AtUtc),record.Sha256,pages,record.Projection);
    }
    internal async Task<SimQuoteDraftView> RenderQuoteCopy(string id,SimQuoteDraftRequest request,SimPersona persona)
    {
        SimQuoteCustomerProjection projection;SimQuotePinnedLine[] lines;var at=DateTimeOffset.UtcNow;var commandHash=EstimateHash(new{id,request});await gate.WaitAsync();try{var prepared=await QuoteProjection(id,request,persona,at);projection=prepared.Projection;lines=prepared.Lines;if(Directory.Exists(QuoteDraftPath(request.RequestId,persona))){var prior=await QuoteDraft(request.RequestId,persona);QuoteRequire(prior.CommandHash==commandHash,"QUOTE_COPY_REPLAY","This preview reference already contains different content.");return await DraftView(prior,persona);}}finally{gate.Release();}
        var rendered=await SimQuotationPdf.RenderDocument(JsonSerializer.SerializeToElement(projection,new JsonSerializerOptions(JsonSerializerDefaults.Web)),"sim_quote_copy_pdf.py",true);using var json=JsonDocument.Parse(rendered);var bytes=Convert.FromBase64String(json.RootElement.GetProperty("pdf").GetString()!);var pages=json.RootElement.GetProperty("pages").EnumerateArray().Select(v=>v.GetString()!).ToArray();QuoteRequire(bytes.Length>500&&Encoding.ASCII.GetString(bytes,0,5)=="%PDF-"&&pages.Length>0,"QUOTE_COPY_RENDER","The customer draft could not be rendered.");
        await gate.WaitAsync();try{await VerifyQuoteLines(lines);await VerifyQuoteRevisionBases(lines,request.RevisionOf);var directory=QuoteDraftPath(request.RequestId,persona);if(Directory.Exists(directory)){var prior=await QuoteDraft(request.RequestId,persona);QuoteRequire(prior.CommandHash==commandHash,"QUOTE_COPY_REPLAY","This preview reference contains other content.");return await DraftView(prior,persona);}var record=new SimQuoteDraftRecord(request.RequestId,commandHash,persona.Id,at,projection,lines,PartHashBytes(bytes),"",request.RevisionOf is {Length:>0}?request.RevisionOf:null);record=record with{ContentHash=DraftHash(record)};Directory.CreateDirectory(Path.GetDirectoryName(directory)!);var temporary=directory+".write-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(temporary);try{await File.WriteAllBytesAsync(Path.Combine(temporary,"quotation.pdf"),bytes);await File.WriteAllTextAsync(Path.Combine(temporary,"pages.json"),JsonSerializer.Serialize(pages,jsonOptions));await File.WriteAllTextAsync(Path.Combine(temporary,"draft.json"),JsonSerializer.Serialize(record,jsonOptions));Directory.Move(temporary,directory);}finally{if(Directory.Exists(temporary))Directory.Delete(temporary,true);}return await DraftView(record,persona);}finally{gate.Release();}
    }
    internal async Task<SimQuoteCopyFile> ReadDraftQuotePdf(string rfqId,string draftId,SimPersona persona)
    {QuotePreparePermission(persona);await gate.WaitAsync();try{var draft=await QuoteDraft(draftId,persona);QuoteRequire(draft.Lines.Any(l=>l.Pair.RfqId==rfqId),"QUOTE_COPY_SCOPE","This PDF belongs to another RFQ selection.");var bytes=await File.ReadAllBytesAsync(Path.Combine(QuoteDraftPath(draftId,persona),"quotation.pdf"));QuoteRequire(PartHashBytes(bytes)==draft.Sha256,"QUOTE_COPY_INTEGRITY","Prepared PDF integrity check failed.");return new(QuoteFileName(draft.Projection,draft.AtUtc),bytes);}finally{gate.Release();}}
    private async Task<SimQuoteCopyRecord> QuoteCopy(string id){var path=QuoteArchivePath(id);QuoteRequire(File.Exists(path),"QUOTE_COPY_UNAVAILABLE","Saved PDF copy is unavailable.");var record=JsonSerializer.Deserialize<SimQuoteCopyRecord>(await File.ReadAllTextAsync(path),jsonOptions)!;QuoteRequire(record.Id==id&&record.ContentHash==CopyHash(record)&&!record.CustomerIssued,"QUOTE_COPY_INTEGRITY","Saved PDF metadata could not be verified.");QuoteRequire(record.ManualSend is null||record.ManualSend.CopyId==record.Id&&record.ManualSend.PdfHash==record.Sha256&&record.ManualSend.PreparedCopyHash==CopyHash(record with{ManualSend=null}),"QUOTE_SEND_INTEGRITY","The original saved copy and manual-send record could not be verified.");return record;}
    private static SimQuoteCopyView CopyView(SimQuoteCopyRecord r)=>new(1,r.Id,QuoteFileName(r.Projection,r.AtUtc),r.Sha256,r.AtUtc,r.ActorName,r.Lines.Select(l=>l.Pair.RfqId).ToArray(),Token:r.ContentHash,ManualSend:r.ManualSend,SourceLines:QuoteCopyLines(r),RevisionOf:r.RevisionOf);
    internal async Task<SimQuoteCopyView> SaveQuoteCopy(string rfqId,SimQuoteSaveRequest request,SimPersona persona)
    {
        QuotePreparePermission(persona);await gate.WaitAsync();try{_=QuoteGuid(request.RequestId);var command=EstimateHash(new{rfqId,request,persona.Id});if(File.Exists(QuoteArchivePath(request.RequestId))){var prior=await QuoteCopy(request.RequestId);QuoteRequire(prior.CommandHash==command&&prior.ActorId==persona.Id,"QUOTE_COPY_REPLAY","This save reference already belongs to different content.");return CopyView(prior);}var draft=await QuoteDraft(request.DraftId,persona);var anchor=await RequireRfqRecord(rfqId);QuoteRequire(draft.ContentHash==request.Token&&anchor.LibraryRfq?.ParentIntakeId==draft.Lines[0].Pair.Binding.ParentIntakeId,"QUOTE_COPY_STALE","Reopen the prepared PDF before saving this copy.");await VerifyQuoteLines(draft.Lines);await VerifyQuoteRevisionBases(draft.Lines,draft.RevisionOf);var bytes=await File.ReadAllBytesAsync(Path.Combine(QuoteDraftPath(draft.Id,persona),"quotation.pdf"));QuoteRequire(PartHashBytes(bytes)==draft.Sha256,"QUOTE_COPY_INTEGRITY","Prepared PDF integrity check failed.");
            var lanes=await ReadRfqLanes();foreach(var item in draft.Lines){var record=await RequireRfqRecord(item.Pair.RfqId);var lane=lanes.GetValueOrDefault(record.IntakeId)??new(new(),new());lanes[record.IntakeId]=RetainEstimatePairs(record,lane);}var lanesText=JsonSerializer.Serialize(lanes,jsonOptions);var laneTemporary=RfqLanesPath+".write-"+Guid.NewGuid().ToString("N");try{await File.WriteAllTextAsync(laneTemporary,lanesText);File.Move(laneTemporary,RfqLanesPath,true);}finally{if(File.Exists(laneTemporary))File.Delete(laneTemporary);}
            var blob=QuoteBlob(draft.Sha256);Directory.CreateDirectory(Path.GetDirectoryName(blob)!);if(!File.Exists(blob)){var temporary=blob+"."+Guid.NewGuid().ToString("N");try{await File.WriteAllBytesAsync(temporary,bytes);File.Move(temporary,blob,false);}finally{if(File.Exists(temporary))File.Delete(temporary);}}QuoteRequire(PartHashBytes(await File.ReadAllBytesAsync(blob))==draft.Sha256,"QUOTE_COPY_INTEGRITY","Saved PDF byte verification failed.");
            var copy=new SimQuoteCopyRecord(request.RequestId,draft.Id,command,persona.Id,persona.DisplayName,DateTimeOffset.UtcNow,draft.Projection,draft.Lines,draft.Sha256,"",RevisionOf:draft.RevisionOf);copy=copy with{ContentHash=CopyHash(copy)};var path=QuoteArchivePath(copy.Id);Directory.CreateDirectory(Path.GetDirectoryName(path)!);var temp=path+".write-"+Guid.NewGuid().ToString("N");try{await File.WriteAllTextAsync(temp,JsonSerializer.Serialize(copy,jsonOptions));File.Move(temp,path,false);}finally{if(File.Exists(temp))File.Delete(temp);}return CopyView(copy);
        }finally{gate.Release();}
    }
    private async Task<object[]> QuoteCopiesForAssembly(string key,string drawingRevision,string bomRevision,string rfqId)
    {
        var directory=Path.Combine(QuoteCopyRoot,"copies");if(!Directory.Exists(directory))return [];var result=new List<object>();foreach(var path in Directory.GetFiles(directory,"*.json")){var copy=await QuoteCopy(Path.GetFileNameWithoutExtension(path));foreach(var line in copy.Lines.Where(l=>l.Pair.RfqId==rfqId&&l.Pair.Binding.LibraryKey==key)){if(!await EstimateRevisionMatches(line.Pair.Binding,key,drawingRevision,bomRevision))continue;var query=new Dictionary<string,string>{{"key",key},{"drawingRevision",drawingRevision},{"bomRevision",bomRevision},{"rfqId",rfqId}};var suffix=string.Join("&",query.Select(q=>Uri.EscapeDataString(q.Key)+"="+Uri.EscapeDataString(q.Value)));result.Add(new{id=copy.Id,copy.AtUtc,copy.ActorName,copy.Sha256,token=copy.ContentHash,name=QuoteFileName(copy.Projection,copy.AtUtc),manualSend=copy.ManualSend,sourceLines=QuoteCopyLines(copy),revisionOf=copy.RevisionOf,estimateId=line.Pair.Id,url=$"/api/sim/assembly-library/quote-copies/{copy.Id}/pdf?{suffix}",customerIssued=false});}}return result.ToArray();
    }
    internal async Task<SimQuoteCopyFile> ReadSavedQuotePdf(string id,string key,string drawingRevision,string bomRevision,string rfqId,SimPersona persona)
    {EstimatePermission(persona);await gate.WaitAsync();try{var copy=await QuoteCopy(id);var line=copy.Lines.SingleOrDefault(l=>l.Pair.RfqId==rfqId);QuoteRequire(line is not null&&await EstimateRevisionMatches(line.Pair.Binding,key,drawingRevision,bomRevision),"QUOTE_COPY_SCOPE","This copy does not belong to this assembly/revision/RFQ.");var record=await RequireRfqRecord(rfqId);_=await VerifyEstimatePair(record,(await ReadRfqLanes()).GetValueOrDefault(rfqId)??new(new(),new()),line!.Pair);var bytes=await File.ReadAllBytesAsync(QuoteBlob(copy.Sha256));QuoteRequire(PartHashBytes(bytes)==copy.Sha256,"QUOTE_COPY_INTEGRITY","Saved PDF byte verification failed.");return new(QuoteFileName(copy.Projection,copy.AtUtc),bytes);}finally{gate.Release();}}
}

internal static partial class SimRfqIntakeEndpoints
{
    private static void MapQuoteCopies(WebApplication app,SimStateStore state,SimRfqIntakeStore store,SimPersonaSessionStore personas)
    {
        MapManualQuoteSends(app,state,store,personas);
        IResult? Permission(HttpContext c,bool archive=false){var denied=DeniedTechnicalReview(c,state,personas,archive?"assembly_library.view":"rfq.quote.prepare");return denied??(archive?DeniedTechnicalReview(c,state,personas,"rfq.view"):null);}
        async Task<IResult> Run(HttpContext c,Func<SimPersona,Task<object>> action,bool archive=false){c.Response.Headers.CacheControl="private, no-store";var denied=Permission(c,archive);if(denied is not null)return denied;try{return Results.Json(await action(personas.Resolve(c)));}catch(SimRfqIntakeProblem e){return Results.Json(new{code=e.Code,message=e.Message},statusCode:e.StatusCode);}catch(Exception e)when(e is IOException or JsonException or System.ComponentModel.Win32Exception){return Results.Json(new{code="QUOTE_COPY_UNCONFIRMED",message="PDF outcome could not be confirmed. Check this copy before retrying."},statusCode:503);}}
        app.MapGet("/api/sim/rfqs/{id}/quote-copies",(string id,HttpContext c)=>Run(c,async p=>await store.ReadQuoteSource(id,p)));
        app.MapPost("/api/sim/rfqs/{id}/quote-copies/preview",(string id,SimQuoteDraftRequest r,HttpContext c)=>Run(c,async p=>await store.RenderQuoteCopy(id,r,p)));
        app.MapPost("/api/sim/rfqs/{id}/quote-copies",(string id,SimQuoteSaveRequest r,HttpContext c)=>Run(c,async p=>await store.SaveQuoteCopy(id,r,p)));
        async Task<IResult> FileResult(HttpContext c,Func<SimPersona,Task<SimQuoteCopyFile>> read,bool archive){var denied=Permission(c,archive);if(denied is not null)return denied;try{var file=await read(personas.Resolve(c));c.Response.Headers.CacheControl="private, no-store";c.Response.Headers["X-Content-Type-Options"]="nosniff";if(c.Request.Query["download"]=="true")return Results.File(file.Bytes,"application/pdf",file.Name);c.Response.Headers.ContentDisposition="inline; filename=\""+file.Name+"\"";return Results.File(file.Bytes,"application/pdf");}catch(SimRfqIntakeProblem e){return Results.Json(new{code=e.Code,message=e.Message},statusCode:e.StatusCode);}catch(IOException){return Results.Json(new{code="QUOTE_COPY_INTEGRITY",message="This PDF could not be verified."},statusCode:503);}}
        app.MapGet("/api/sim/rfqs/{id}/quote-copies/drafts/{draftId}/pdf",(string id,string draftId,HttpContext c)=>FileResult(c,p=>store.ReadDraftQuotePdf(id,draftId,p),false));
        app.MapGet("/api/sim/assembly-library/quote-copies/{copyId}/pdf",(string copyId,string key,string drawingRevision,string bomRevision,string rfqId,HttpContext c)=>FileResult(c,p=>store.ReadSavedQuotePdf(copyId,key,drawingRevision,bomRevision,rfqId,p),true));
    }
}
